  <div class="dlu-404__inner">
    <div class="dlu-404__art" aria-hidden="true">
      <span class="dlu-404__art-circle dlu-404__art-circle--one"></span>
      <span class="dlu-404__art-circle dlu-404__art-circle--two"></span>
      <span class="dlu-404__art-spark dlu-404__art-spark--one">✦</span>
      <span class="dlu-404__art-spark dlu-404__art-spark--two">✦</span>
      <svg class="dlu-404__illustration" viewBox="0 0 420 330" role="presentation" focusable="false">
        <ellipse cx="214" cy="286" rx="130" ry="15" fill="#1B3C73" opacity=".08"></ellipse>
