        <circle cx="322" cy="69" r="7" fill="#F7D52C"></circle>
        <circle cx="87" cy="101" r="5" fill="#DF408A"></circle>
        <path d="m314 109 5 10 11 2-8 8 2 11-10-5-10 5 2-11-8-8 11-2 5-10Z" fill="#F7D52C" opacity=".95"></path>
        <path d="m88 217 4 8 9 1-7 6 2 9-8-4-8 4 2-9-7-6 9-1 4-8Z" fill="#7FB32C"></path>
        <g transform="rotate(-7 210 166)">
          <rect x="125" y="65" width="164" height="205" rx="17" fill="#1B3C73" opacity=".10" transform="translate(5 8)"></rect>
          <rect x="125" y="60" width="164" height="205" rx="17" fill="#FFFFFF" stroke="#DCE6D3" stroke-width="2"></rect>
          <path d="M250 60h22a17 17 0 0 1 17 17v22Z" fill="#EFF7E7"></path>
          <rect x="147" y="84" width="55" height="8" rx="4" fill="#E9EEF2"></rect>
          <rect x="147" y="101" width="95" height="6" rx="3" fill="#E9EEF2"></rect>
          <text x="207" y="171" text-anchor="middle" font-family="Arial, sans-serif" font-size="57" font-weight="800" fill="#7FB32C">404</text>
