          <path d="M166 207h80" stroke="#E4EBDD" stroke-width="5" stroke-linecap="round"></path>
          <rect x="164" y="226" width="86" height="20" rx="10" fill="#1B3C73"></rect>
          <circle cx="178" cy="236" r="3" fill="#7FB32C"></circle>
          <path d="M188 236h48" stroke="#FFFFFF" stroke-width="3" stroke-linecap="round" opacity=".9"></path>
        </g>
        <g transform="rotate(12 290 220)">
          <circle cx="289" cy="208" r="38" fill="#FFFFFF" stroke="#1881C1" stroke-width="11"></circle>
          <circle cx="289" cy="208" r="25" fill="#EAF6FC"></circle>
          <path d="m317 236 31 31" stroke="#1881C1" stroke-width="14" stroke-linecap="round"></path>
          <path d="m319 239 26 26" stroke="#7FB32C" stroke-width="4" stroke-linecap="round"></path>
        </g>
        <g transform="rotate(28 107 213)">
          <rect x="95" y="165" width="23" height="99" rx="5" fill="#DF408A"></rect>
          <path d="M95 173h23" stroke="#FFFFFF" stroke-width="4" opacity=".9"></path>
