      </svg>
    </div>

    <div class="dlu-404__content">
      <p class="dlu-404__eyebrow"><span aria-hidden="true"></span> ERROR 404</p>
      <h1 id="dlu-404-title" class="dlu-404__title">
        ¡Ups! Esta página <span>no existe.</span>
      </h1>
      <p class="dlu-404__text">
        El enlace puede haber cambiado o la página ya no está disponible.
      </p>
      <a class="dlu-404__button" href="{{ routes.root_url }}">
        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
          <path d="M19 12H5M12 19l-7-7 7-7"></path>
        </svg>
        Volver al inicio
      </a>
