<style>
  #dlu-custom-404 {
    --dlu-green: #7fb32c;
    --dlu-green-dark: #61921f;
    --dlu-blue: #1881c1;
    --dlu-navy: #1b3c73;
    --dlu-ink: #202126;
    --dlu-muted: #656b73;
    width: 100%;
    min-height: 420px;
    padding: 28px 22px 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #ffffff;
    box-sizing: border-box;
    overflow: hidden;
  }

  #dlu-custom-404 *,
  #dlu-custom-404 *::before,
  #dlu-custom-404 *::after { box-sizing: border-box; }

  #dlu-custom-404 .dlu-404__inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: min(860px, 100%);
    margin: 0 auto;
    text-align: center;
  }

  #dlu-custom-404 .dlu-404__art {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: min(280px, 72vw);
    margin: 0 auto 6px;
    animation: dlu-404-enter .75s cubic-bezier(.2,.75,.25,1) both;
  }

  #dlu-custom-404 .dlu-404__illustration {
    position: relative;
    z-index: 1;
    display: block;
    width: 100%;
    height: auto;
    overflow: visible;
    transform-origin: 50% 75%;
    animation: dlu-404-float 4.5s ease-in-out 0.8s infinite;
  }

  #dlu-custom-404 .dlu-404__art-circle {
    position: absolute;
    display: block;
    border-radius: 50%;
    pointer-events: none;
    animation: dlu-404-pulse 3.2s ease-in-out infinite;
  }

  #dlu-custom-404 .dlu-404__art-circle--one {
    top: 13%; right: 2%; width: 31px; height: 31px;
    border: 6px solid rgba(127, 179, 44, .2);
  }

  #dlu-custom-404 .dlu-404__art-circle--two {
    bottom: 17%; left: 1%; width: 16px; height: 16px;
    background: rgba(24, 129, 193, .16);
    animation-delay: .7s;
  }

  #dlu-custom-404 .dlu-404__art-spark {
    position: absolute;
    z-index: 2;
    color: var(--dlu-green);
    font-size: 22px;
    line-height: 1;
    animation: dlu-404-twinkle 2.4s ease-in-out infinite;
  }

  #dlu-custom-404 .dlu-404__art-spark--one { top: 28%; left: 5%; }
  #dlu-custom-404 .dlu-404__art-spark--two { right: 1%; bottom: 25%; color: #f7d52c; font-size: 17px; animation-delay: .8s; }

  #dlu-custom-404 .dlu-404__content {
    display: flex;
    flex-direction: column;
    align-items: center;
    animation: dlu-404-enter .8s cubic-bezier(.2,.75,.25,1) .12s both;
  }

  #dlu-custom-404 .dlu-404__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    margin: 0 0 12px;
    color: var(--dlu-green-dark);
    font-family: inherit;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: .15em;
    line-height: 1.4;
  }

  #dlu-custom-404 .dlu-404__eyebrow span {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--dlu-green);
    box-shadow: 0 0 0 4px rgba(127, 179, 44, .13);
  }

  #dlu-custom-404 .dlu-404__title {
    max-width: 760px;
    margin: 0;
    color: var(--dlu-ink);
    font-family: inherit;
    font-size: clamp(30px, 4vw, 42px);
    font-weight: 750;
    letter-spacing: -.035em;
    line-height: 1.15;
    text-wrap: balance;
  }

  #dlu-custom-404 .dlu-404__title span {
    color: var(--dlu-green);
  }

  #dlu-custom-404 .dlu-404__text {
    max-width: 500px;
    margin: 13px 0 22px;
    color: var(--dlu-muted);
    font-family: inherit;
    font-size: 15px;
    line-height: 1.65;
  }

  #dlu-custom-404 .dlu-404__button {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-height: 50px;
    padding: 14px 23px;
    border: 0;
    border-radius: 12px;
    color: #ffffff;
    background: var(--dlu-blue);
    box-shadow: 0 6px 0 rgba(27, 60, 115, .08), 0 9px 20px rgba(24, 129, 193, .17);
    font-family: inherit;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: transform .22s ease, background .22s ease, box-shadow .22s ease;
  }

  #dlu-custom-404 .dlu-404__button:hover {
    transform: translateY(-3px);
    background: var(--dlu-navy);
    box-shadow: 0 10px 24px rgba(27, 60, 115, .18);
  }

  #dlu-custom-404 .dlu-404__button:focus-visible {
    outline: 3px solid rgba(127, 179, 44, .6);
    outline-offset: 4px;
  }

  #dlu-custom-404 .dlu-404__button svg {
    display: block;
    width: 17px;
    height: 17px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: transform .22s ease;
  }

  #dlu-custom-404 .dlu-404__button:hover svg { transform: translateX(-3px); }

  @keyframes dlu-404-enter {
    from { opacity: 0; transform: translateY(18px); }
    to { opacity: 1; transform: translateY(0); }
  }

  @keyframes dlu-404-float {
    0%, 100% { transform: translateY(0) rotate(0); }
    50% { transform: translateY(-8px) rotate(-1deg); }
  }

  @keyframes dlu-404-pulse {
    0%, 100% { transform: scale(1); opacity: .7; }
    50% { transform: scale(1.12); opacity: 1; }
  }

  @keyframes dlu-404-twinkle {
    0%, 100% { transform: scale(.8) rotate(0); opacity: .55; }
    50% { transform: scale(1.14) rotate(12deg); opacity: 1; }
  }

  @media screen and (max-width: 640px) {
    #dlu-custom-404 { min-height: 390px; padding: 24px 18px 36px; }
    #dlu-custom-404 .dlu-404__art { width: min(235px, 68vw); margin-bottom: 4px; }
    #dlu-custom-404 .dlu-404__title { font-size: clamp(29px, 8vw, 36px); }
    #dlu-custom-404 .dlu-404__text { max-width: 360px; margin: 11px 0 19px; font-size: 14px; }
    #dlu-custom-404 .dlu-404__button { min-height: 48px; padding: 13px 21px; }
  }

  @media (prefers-reduced-motion: reduce) {
    #dlu-custom-404 *,
    #dlu-custom-404 *::before,
    #dlu-custom-404 *::after {
      animation: none !important;
      transition: none !important;
      scroll-behavior: auto !important;
    }
  }
</style>
